          saslServer = Sasl.createSaslServer(AuthMethod.DIGEST
              .getMechanismName(), null, SaslRpcServer.SASL_DEFAULT_REALM,
              SaslRpcServer.SASL_PROPS, new SaslDigestCallbackHandler(
                  secretManager, this));
          break;
        default:
          UserGroupInformation current = UserGroupInformation
              .getCurrentUser();
          String fullName = current.getUserName();
          if (LOG.isDebugEnabled())
            LOG.debug("Kerberos principal name is " + fullName);
          final String names[] = SaslRpcServer.splitKerberosName(fullName);
          if (names.length != 3) {
            throw new AccessControlException(
                "Kerberos principal name does NOT have the expected "
                    + "hostname part: " + fullName);
          }
          current.doAs(new PrivilegedExceptionAction<Object>() {
            @Override
            public Object run() throws SaslException {
              saslServer = Sasl.createSaslServer(AuthMethod.KERBEROS
                  .getMechanismName(), names[0], names[1],
                  SaslRpcServer.SASL_PROPS, new SaslGssCallbackHandler());
              return null;
            }
          });
        }
        if (saslServer == null)
          throw new AccessControlException(
              "Unable to find SASL server implementation for "
                  + authMethod.getMechanismName());
        if (LOG.isDebugEnabled())
          LOG.debug("Created SASL server with mechanism = "
              + authMethod.getMechanismName());
      }
      if (LOG.isDebugEnabled())
        LOG.debug("Have read input token of size " + saslToken.length
            + " for processing by saslServer.evaluateResponse()");
      replyToken = saslServer.evaluateResponse(saslToken);
    } catch (IOException e) {
      IOException sendToClient = e;
      Throwable cause = e;
      while (cause != null) {
        if (cause instanceof InvalidToken) {
          sendToClient = (InvalidToken) cause;
          break;
        }
        cause = cause.getCause();
      }
      doSaslReply(SaslStatus.ERROR, null, sendToClient.getClass().getName(), 
          sendToClient.getLocalizedMessage());
      rpcMetrics.authenticationFailures.inc();
      String clientIP = this.toString();
      // attempting user could be null
      AUDITLOG.warn(AUTH_FAILED_FOR + clientIP + ":" + attemptingUser);
      throw e;
    }
    if (replyToken != null) {
      if (LOG.isDebugEnabled())
        LOG.debug("Will send token of size " + replyToken.length
            + " from saslServer.");
      doSaslReply(SaslStatus.SUCCESS, new BytesWritable(replyToken), null,
          null);
    }
    if (saslServer.isComplete()) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("SASL server context established. Negotiated QoP is "
            + saslServer.getNegotiatedProperty(Sasl.QOP));
      }
      user = getAuthorizedUgi(saslServer.getAuthorizationID());
      LOG.info("SASL server successfully authenticated client: " + user);
      rpcMetrics.authenticationSuccesses.inc();
      AUDITLOG.info(AUTH_SUCCESSFULL_FOR + user);
      saslContextEstablished = true;
    }
  } else {
    if (LOG.isDebugEnabled())
      LOG.debug("Have read input token of size " + saslToken.length
          + " for processing by saslServer.unwrap()");
    byte[] plaintextData = saslServer
        .unwrap(saslToken, 0, saslToken.length);
    processUnwrappedData(plaintextData);
  }
}

private void doSaslReply(SaslStatus status, Writable rv,
    String errorClass, String error) throws IOException {
  saslResponse.reset();
  DataOutputStream out = new DataOutputStream(saslResponse);
  out.writeInt(status.state); // write status
  if (status == SaslStatus.SUCCESS) {
    rv.write(out);
  } else {
    WritableUtils.writeString(out, errorClass);
    WritableUtils.writeString(out, error);
  }
  saslCall.setResponse(ByteBuffer.wrap(saslResponse.toByteArray()));
  responder.doRespond(saslCall);
}

private void disposeSasl() {
  if (saslServer != null) {
    try {
      saslServer.dispose();
    } catch (SaslException ignored) {
    }
  }
}

public int readAndProcess() throws IOException, InterruptedException {
  while (true) {
    /* Read at most one RPC. If the header is not read completely yet
     * then iterate until we read first RPC or until there is no data left.
     */    
    int count = -1;
    if (dataLengthBuffer.remaining() > 0) {
      count = channelRead(channel, dataLengthBuffer);       
      if (count < 0 || dataLengthBuffer.remaining() > 0) 
        return count;
    }

    if (!rpcHeaderRead) {
      //Every connection is expected to send the header.
      if (rpcHeaderBuffer == null) {
        rpcHeaderBuffer = ByteBuffer.allocate(2);
      }
      count = channelRead(channel, rpcHeaderBuffer);
      if (count < 0 || rpcHeaderBuffer.remaining() > 0) {
        return count;
      }
      int version = rpcHeaderBuffer.get(0);
      byte[] method = new byte[] {rpcHeaderBuffer.get(1)};
      authMethod = AuthMethod.read(new DataInputStream(
          new ByteArrayInputStream(method)));
      if (authMethod == null) {
        throw new IOException("Unable to read authentication method");
      }
      if (isSecurityEnabled && authMethod == AuthMethod.SIMPLE) {
        AccessControlException ae = new AccessControlException(
            "Authentication is required");
        setupResponse(authFailedResponse, authFailedCall, Status.FATAL,
            null, ae.getClass().getName(), ae.getMessage());
        responder.doRespond(authFailedCall);
        throw ae;
      }
      if (!isSecurityEnabled && authMethod != AuthMethod.SIMPLE) {
        doSaslReply(SaslStatus.SUCCESS, new IntWritable(
            SaslRpcServer.SWITCH_TO_SIMPLE_AUTH), null, null);
        authMethod = AuthMethod.SIMPLE;
        // client has already sent the initial Sasl message and we
        // should ignore it. Both client and server should fall back
        // to simple auth from now on.
        skipInitialSaslHandshake = true;
      }
      if (authMethod != AuthMethod.SIMPLE) {
        useSasl = true;
      }

      dataLengthBuffer.flip();          
      if (!HEADER.equals(dataLengthBuffer) || version != CURRENT_VERSION) {
        //Warning is ok since this is not supposed to happen.
        LOG.warn("Incorrect header or version mismatch from " + 
                 hostAddress + ":" + remotePort +
                 " got version " + version + 
                 " expected version " + CURRENT_VERSION);
        return -1;
      }
      dataLengthBuffer.clear();
      rpcHeaderBuffer = null;
      rpcHeaderRead = true;
      continue;
    }

    if (data == null) {
      dataLengthBuffer.flip();
      dataLength = dataLengthBuffer.getInt();

      if (!useSasl && dataLength == Client.PING_CALL_ID) {
        dataLengthBuffer.clear();
        return 0;  //ping message
      }
      data = ByteBuffer.allocate(dataLength);
    }

    count = channelRead(channel, data);

    if (data.remaining() == 0) {
      dataLengthBuffer.clear();
      data.flip();
      if (skipInitialSaslHandshake) {
        data = null;
        skipInitialSaslHandshake = false;
        continue;
      }
      boolean isHeaderRead = headerRead;
      if (useSasl) {
        saslReadAndProcess(data.array());
      } else {
        processOneRpc(data.array());
      }
      data = null;
      if (!isHeaderRead) {
        continue;
      }
    } 
    return count;
  }
}

/// Reads the connection header following version
private void processHeader(byte[] buf) throws IOException {
  DataInputStream in =
    new DataInputStream(new ByteArrayInputStream(buf));
  header.readFields(in);
  try {
    String protocolClassName = header.getProtocol();
    if (protocolClassName != null) {
      protocol = getProtocolClass(header.getProtocol(), conf);
    }
  } catch (ClassNotFoundException cnfe) {
    throw new IOException("Unknown protocol: " + header.getProtocol());
  }

  UserGroupInformation protocolUser = header.getUgi();
  if (!useSasl) {
    user = protocolUser;
    if (user != null) {
      user.setAuthenticationMethod(AuthMethod.SIMPLE.authenticationMethod);
    }
  } else {
    // user is authenticated
    user.setAuthenticationMethod(authMethod.authenticationMethod);
    //Now we check if this is a proxy user case. If the protocol user is
    //different from the 'user', it is a proxy user scenario. However, 
    //this is not allowed if user authenticated with DIGEST.
    if ((protocolUser != null)
        && (!protocolUser.getUserName().equals(user.getUserName()))) {
      if (authMethod == AuthMethod.DIGEST) {
        // Not allowed to doAs if token authentication is used
        throw new AccessControlException("Authenticated user (" + user
            + ") doesn't match what the client claims to be ("
            + protocolUser + ")");
      } else {
        // Effective user can be different from authenticated user
        // for simple auth or kerberos auth
        // The user is the real user. Now we create a proxy user
        UserGroupInformation realUser = user;
        user = UserGroupInformation.createProxyUser(protocolUser
            .getUserName(), realUser);
        // Now the user is a proxy user, set Authentication method Proxy.
        user.setAuthenticationMethod(AuthenticationMethod.PROXY);
      }
    }
  }
}

private void processUnwrappedData(byte[] inBuf) throws IOException,
    InterruptedException {
  ReadableByteChannel ch = Channels.newChannel(new ByteArrayInputStream(
      inBuf));
  // Read all RPCs contained in the inBuf, even partial ones
  while (true) {
    int count = -1;
    if (unwrappedDataLengthBuffer.remaining() > 0) {
      count = channelRead(ch, unwrappedDataLengthBuffer);
      if (count <= 0 || unwrappedDataLengthBuffer.remaining() > 0)
        return;
    }

    if (unwrappedData == null) {
      unwrappedDataLengthBuffer.flip();
      int unwrappedDataLength = unwrappedDataLengthBuffer.getInt();

      if (unwrappedDataLength == Client.PING_CALL_ID) {
        if (LOG.isDebugEnabled())
          LOG.debug("Received ping message");
        unwrappedDataLengthBuffer.clear();
        continue; // ping message
      }
      unwrappedData = ByteBuffer.allocate(unwrappedDataLength);
    }

    count = channelRead(ch, unwrappedData);
    if (count <= 0 || unwrappedData.remaining() > 0)
      return;

    if (unwrappedData.remaining() == 0) {
      unwrappedDataLengthBuffer.clear();
      unwrappedData.flip();
      processOneRpc(unwrappedData.array());
      unwrappedData = null;
    }
  }
}

private void processOneRpc(byte[] buf) throws IOException,
    InterruptedException {
  if (headerRead) {
    processData(buf);
  } else {
    processHeader(buf);
    headerRead = true;
    if (!authorizeConnection()) {
      throw new AccessControlException("Connection from " + this
          + " for protocol " + header.getProtocol()
          + " is unauthorized for user " + user);
    }
  }
}

private void processData(byte[] buf) throws  IOException, InterruptedException {
  DataInputStream dis =
    new DataInputStream(new ByteArrayInputStream(buf));
  int id = dis.readInt();                    // try to read an id

  if (LOG.isDebugEnabled())
    LOG.debug(" got #" + id);

  Writable param = ReflectionUtils.newInstance(paramClass, conf);//read param
  param.readFields(dis);        

  Call call = new Call(id, param, this);
  callQueue.put(call);              // queue the call; maybe blocked here
  incRpcCount();  // Increment the rpc count
}

